package panel

func networkPolicyAPISpec(paths, schemas Data) {
	paths["/api/nodes/{id}/geo-assets"] = Data{"parameters": []any{Data{"name": "id", "in": "path", "required": true, "schema": Data{"type": "integer", "minimum": 1}}}, "get": Data{"summary": "Administrator-only read-only installed Xray GeoIP/Geosite tag index, counts and SHA-256; read-scoped admin keys supported", "parameters": []any{Data{"name": "kind", "in": "query", "required": true, "schema": Data{"type": "string", "enum": []any{"geoip", "geosite"}}}, Data{"name": "q", "in": "query", "schema": Data{"type": "string", "maxLength": 96}}, Data{"name": "limit", "in": "query", "schema": Data{"type": "integer", "minimum": 1, "maximum": 100, "default": 100}}}, "responses": Data{"200": Data{"description": "Bounded tag index and asset metadata; no filesystem paths or domain/IP contents"}, "400": Data{"description": "Invalid search"}, "403": Data{"description": "Administrator required"}, "502": Data{"description": "Agent or installed assets unavailable"}}}}
	text := Data{"type": "string"}
	tag := Data{"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,95}$"}
	balancer := Data{"type": "object", "additionalProperties": false, "required": []any{"tag", "selector"}, "properties": Data{"tag": tag, "selector": Data{"type": "array", "minItems": 1, "maxItems": 64, "uniqueItems": true, "items": tag, "description": "Xray outbound tag prefixes; each must match an enabled merged outbound"}, "fallbackTag": text, "strategy": Data{"type": "object", "additionalProperties": false, "properties": Data{"type": Data{"type": "string", "description": "Case-insensitive random, roundRobin, leastPing or leastLoad; latency strategies require an operator-configured observatory"}, "settings": Data{"type": "object"}}}}}
	schemas["XrayBalancer"] = balancer
	schemas["XrayBalancingInput"] = Data{"type": "object", "additionalProperties": false, "required": []any{"revision", "balancers"}, "properties": Data{"revision": Data{"type": "string", "pattern": "^[a-f0-9]{64}$", "description": "Current GET revision for compare-and-set"}, "balancers": Data{"type": "array", "maxItems": 64, "items": Data{"$ref": "#/components/schemas/XrayBalancer"}}}}
	schemas["InboundFallback"] = Data{"type": "object", "additionalProperties": false, "required": []any{"dest"}, "properties": Data{"name": Data{"type": "string", "maxLength": 255}, "alpn": Data{"type": "string", "maxLength": 255}, "path": Data{"type": "string", "maxLength": 255}, "dest": Data{"oneOf": []any{Data{"type": "integer", "minimum": 1, "maximum": 65535}, Data{"type": "string", "maxLength": 255}}, "description": "Port, host:port, absolute Unix socket or @abstract socket; not an HTTP URL"}, "xver": Data{"type": "integer", "enum": []any{0, 1, 2}}}}
	input := Data{"type": "object", "additionalProperties": true, "properties": Data{"protocol_settings": Data{"type": "object", "additionalProperties": true, "properties": Data{"fallbacks": Data{"type": "array", "maxItems": 32, "items": Data{"$ref": "#/components/schemas/InboundFallback"}, "description": "Xray VLESS/Trojan RAW, TLS/none only. Overall empty-name/ALPN/path default and empty-path default for each name/ALPN group required. Other existing inbound fields also accepted."}}}}}
	request := Data{"required": true, "content": Data{"application/json": Data{"schema": input}}}
	obj(obj(paths, "/api/inbounds"), "post")["requestBody"] = request
	obj(obj(paths, "/api/inbounds/{id}"), "patch")["requestBody"] = request
	paths["/api/nodes/{id}/balancing"] = Data{"parameters": []any{Data{"name": "id", "in": "path", "required": true, "schema": Data{"type": "integer", "minimum": 1}}}, "get": Data{"summary": "Administrator-only effective Xray balancers, outbound tags, observatory availability and revision; read-scoped admin keys supported", "responses": Data{"200": Data{"description": "Resolved profile/node balancers without outbound credentials"}, "403": Data{"description": "Administrator required"}}}, "put": Data{"summary": "Administrator-scoped atomic balancer replacement and compensated node deployment; preserves unrelated settings", "requestBody": Data{"required": true, "content": Data{"application/json": Data{"schema": Data{"$ref": "#/components/schemas/XrayBalancingInput"}}}}, "responses": Data{"200": Data{"description": "Deployed balancing view"}, "400": Data{"description": "Invalid graph or input"}, "403": Data{"description": "Administrator scope required"}, "409": Data{"description": "Revision changed; reload first"}, "502": Data{"description": "Node validation/deployment failed; previous state retained"}}}}
}
